# Generate K_{6,7} as a maximal triangle-free graph on 13 vertices
# Part 1: vertices 0-5 (6 vertices)
# Part 2: vertices 6-12 (7 vertices)

edges = []
for u in range(6):
    for v in range(6, 13):
        edges.append((u, v))

print(f"Number of edges: {len(edges)}")
print("Edges:", edges)

# Verify triangle-free
def has_triangle(edges, n):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for u in range(n):
        for v in adj[u]:
            if v > u:
                for w in adj[u]:
                    if w > v and w in adj[v]:
                        return True, (u, v, w)
    return False, None

is_triangle_free, triangle = has_triangle(edges, 13)
print(f"Triangle-free: {is_triangle_free}")
if not is_triangle_free:
    print(f"Triangle found: {triangle}")

# Verify maximal: adding any non-edge creates a triangle
def is_maximal_triangle_free(edges, n):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check all non-edges
    for u in range(n):
        for v in range(u+1, n):
            if v not in adj[u]:
                # Adding (u, v) should create a triangle
                # This means there should exist w such that w is adjacent to both u and v
                common_neighbors = adj[u] & adj[v]
                if len(common_neighbors) == 0:
                    return False, (u, v)
    return True, None

is_maximal, non_maximal_pair = is_maximal_triangle_free(edges, 13)
print(f"Maximal triangle-free: {is_maximal}")
if not is_maximal:
    print(f"Non-maximal pair: {non_maximal_pair}")
